- (UIButton*)button:(NSString*)title symbol:(NSString*)symbol action:(SEL)action{UIButton *b=[UIButton buttonWithType:UIButtonTypeSystem];if(symbol.length)[b setImage:[UIImage systemImageNamed:symbol] forState:UIControlStateNormal];else[b setTitle:title forState:UIControlStateNormal];b.accessibilityLabel=title;[b addTarget:self action:action forControlEvents:UIControlEventTouchUpInside];return b;}
- (void)viewDidLoad{[super viewDidLoad];self.overrideUserInterfaceStyle=UIUserInterfaceStyleDark;self.view.backgroundColor=PVXBG(17);self.rows=@[];self.allRows=@[];self.selection=[NSMutableSet set];self.pending=[NSMutableSet set];self.submissions=[NSMutableDictionary dictionary];self.closeButton=[self button:@"关闭" symbol:@"xmark" action:@selector(close)];self.selectionButton=[self button:@"多选" symbol:@"checkmark.square" action:@selector(toggleSelection)];self.mainTabs=[[UISegmentedControl alloc] initWithItems:@[@"下载",@"采集"]];self.mainTabs.selectedSegmentIndex=0;[self.mainTabs addTarget:self action:@selector(modeChanged) forControlEvents:UIControlEventValueChanged];self.mediaTabs=[[UISegmentedControl alloc] initWithItems:@[@"全部",@"视频",@"图片"]];self.mediaTabs.selectedSegmentIndex=0;[self.mediaTabs addTarget:self action:@selector(filterChanged) forControlEvents:UIControlEventValueChanged];self.spaceLabel=[UILabel new];self.spaceLabel.textColor=UIColor.secondaryLabelColor;self.spaceLabel.font=[UIFont monospacedDigitSystemFontOfSize:11 weight:UIFontWeightMedium];self.spaceLabel.textAlignment=NSTextAlignmentCenter;self.spaceLabel.text=@"正在读取本地下载文件占用…";self.search=[UISearchBar new];self.search.placeholder=@"搜索标题、URL、分组或标签";self.search.searchBarStyle=UISearchBarStyleMinimal;self.search.delegate=self;self.sectionLabel=[UILabel new];self.sectionLabel.textColor=UIColor.whiteColor;self.sectionLabel.font=[UIFont systemFontOfSize:16 weight:UIFontWeightBold];self.sectionLabel.userInteractionEnabled=YES;[self.sectionLabel addGestureRecognizer:[[UITapGestureRecognizer alloc] initWithTarget:self action:@selector(collapse)]];self.allButton=[self button:@"全选" symbol:nil action:@selector(selectAll)];self.allButton.hidden=YES;self.feedback=[UILabel new];self.feedback.font=[UIFont systemFontOfSize:12];self.feedback.textColor=UIColor.secondaryLabelColor;self.feedback.numberOfLines=2;self.feedback.text=@"下载完成后点“导出”，选择保存到相册或文件。";self.table=[[UITableView alloc] initWithFrame:CGRectZero style:U