- (void)viewDidAppear:(BOOL)animated{[super viewDidAppear:animated];self.visible=YES;__weak typeof(self)weak=self;self.timer=[NSTimer timerWithTimeInterval:1 repeats:YES block:^(NSTimer *timer){if(weak.visible&&weak.view.window&&!weak.presentedViewController&&UIApplication.sharedApplication.applicationState==UIApplicationStateActive)[weak readData];}];[[NSRunLoop mainRunLoop] addTimer:self.timer forMode:NSRunLoopCommonModes];[self readData];}
