- (void)dealloc{[_timer invalidate];[[NSNotificationCenter defaultCenter] removeObserver:self];}
- (void)close{[self dismissViewControllerAnimated:YES completion:nil];}
- (NSString*)kind{return self.mediaTabs.selectedSegmentIndex==1?@"video":self.mediaTabs.selectedSegmentIndex==2?@"image":@"all";}
- (void)modeChanged{self.selecting=NO;self.collapsed=NO;[self.selection removeAllObjects];self.allButton.hidden=YES;self.batchBar.hidden=YES;[self.selectionButton setImage:[UIImage systemImageNamed:@"checkmark.square"] forState:UIControlStateNormal];[self.view setNeedsLayout];if(self.mainTabs.selectedSegmentIndex==1)PVXRefreshCollection();[self readData];}
- (void)filterChanged{[self.selection removeAllObjects];if(self.mainTabs.selectedSegmentIndex==1)[self readData];else[self applyFilter:YES];}
- (void)refresh{PVXRefreshCollection();[self readData];[self.table.refreshControl endRefreshing];}
- (void)collectionChanged:(NSNotification*)note{if(self.mainTabs.selectedSegmentIndex==1&&!self.presentedViewController)[self readData];}
- (void)collapse{self.collapsed=!self.collapsed;[self applyFilter:YES];}
- (void)readData{if(self.reading)return;if(self.mainTabs.selectedSegmentIndex==1){NSMutableArray *list=[PVXCollectedMedia(self.kind) mutableCopy]?:[NSMutableArray array];for(NSUInteger i=0;i<list.count;i++){NSDictionary *r=list[i];NSString *key=PVXRowID(r);if([self.pending containsObject:key]){NSMutableDictionary *m=[r mutableCopy];m[@"submissionState"]=@"正在提交请求…";list[i]=m;}else if(self.submissions[key]){NSMutableDictionary *m=[r mutableCopy];m[@"submissionState"]=@"已提交 · 下载页可查看状态";list[i]=m;}}self.allRows=list;[self applyFilter:NO];return;}self.reading=YES;dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY,0),^{NSArray *rows=PVXReadVideoTasks();NSDictionary *space=PVXStorageSummary();dispatch_async(dispatch_get_main_queue(),^{self.reading=NO;if(self.mainTabs.selectedSegmentIndex!=0)return;self.allRows=rows;self.spaceLabel.text=PVXText(space[@"text"]);[self applyFilter:NO];});});}
