- (void)searchBar:(UISearchBar*)search textDidChange:(NSString*)text{[self applyFilter:YES];}
- (void)searchBarSearchButtonClicked:(UISearchBar*)search{[search resignFirstResponder];}
- (NSInteger)tableView:(UITableView*)table numberOfRowsInSection:(NSInteger)section{return self.collapsed?0:self.rows.count;}
- (UITableViewCell*)tableView:(UITableView*)table cellForRowAtIndexPath:(NSIndexPath*)path{PVXMediaRow *cell=[table dequeueReusableCellWithIdentifier:@"media" forIndexPath:path];NSDictionary *r=self.rows[path.row];[cell render:r collect:self.mainTabs.selectedSegmentIndex==1 selecting:self.selecting selected:[self.selection containsObject:PVXRowID(r)]];__weak typeof(self)weak=self;cell.pressed=^(NSString *identity,UIView *anchor){[weak commandForID:identity anchor:anchor];};return cell;}
- (NSDictionary*)rowForID:(NSString*)key{for(NSDictionary *r in self.rows)if([PVXRowID(r) isEqual:key])return r;return nil;}
- (void)commandForID:(NSString*)key anchor:(UIView*)anchor{NSDictionary *r=[self rowForID:key];if(!r)return;if(self.selecting){[self toggleRow:r];return;}if(self.mainTabs.selectedSegmentIndex==1){[self submitRows:@[r]];return;}[self showMenu:@[r] anchor:anchor];}
- (void)tableView:(UITableView*)table didSelectRowAtIndexPath:(NSIndexPath*)path{[table deselectRowAtIndexPath:path animated:YES];if(path.row<0||(NSUInteger)path.row>=self.rows.count)return;NSDictionary *r=self.rows[path.row];if(self.selecting)[self toggleRow:r];else if(self.mainTabs.selectedSegmentIndex==1)[self submitRows:@[r]];else[self showMenu:@[r] anchor:[table cellForRowAtIndexPath:path]];}
- (void)toggleRow:(NSDictionary*)r{NSString *key=PVXRowID(r);if([self.selection containsObject:key])[self.selection removeObject:key];else[self.selection addObject:key];[self applyFilter:NO];}
- (void)toggleSelection{self.selecting=!self.selecting;[self.selection removeAllObjects];self.allButton.hidden=!self.selecting;self.batchBar.hidden=!self.selecting;[self.selectionButton setImage:[UIImage systemImageNamed:self.selecting?@"xmark.square":@"checkmark.square"] forState:UIControlStateNormal];[self.batchExport setTitle:self.mainTabs.selectedSegmentIndex?@"下载所选":@"导出" forState:UIControlStateNormal];self.batchDelete.hidden=self.mainTabs.selectedSegmentIndex==1;self.batchMore.hidden=self.mainTabs.selectedSegmentIndex==1;[self.view setNeedsLayout];[self applyFilter:NO];}
- (void)selectAll{if(self.selection.count==self.rows.count)[self.selection removeAllObjects];else for(NSDictionary *r in self.rows)[self.selection addObject:PVXRowID(r)];[self applyFilter:NO];}
- (NSArray*)selectedRows{NSMutableArray *rows=[NSMutableArray array];for(NSDictionary *r in self.rows)if([self.selection containsObject:PVXRowID(r)])[rows addObject:r];return rows;}
- (void)exportSelected{NSArray *rows=[self selectedRows];if(self.mainTabs.selectedSegmentIndex){[self submitRows:rows];return;}[self exportRows:rows anchor:self.batchExport];}
- (void)exportRows:(NSArray*)rows anchor:(UIView*)anchor{for(NSDictionary *r in rows)if(!PVXTaskHasLocalFile(r)){PVXAlert(@"暂时不能导出",@"所选项目中包含尚未下载完成或没有本地原文件的任务。请完成下载后再导出。");return;}if(rows.count)PVXExportTasks(rows,anchor);}
