ionWithTitle:@"查看状态详情" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){PVXAlert(@"任务状态",first[@"error"]);}]];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];a.popoverPresentationController.sourceView=anchor?:self.view;a.popoverPresentationController.sourceRect=anchor?anchor.bounds:CGRectMake(self.view.bounds.size.width/2,self.view.bounds.size.height/2,1,1);[self presentViewController:a animated:YES completion:nil];}
